var n = 10000;

var m = new Array(n);
var x = new Array(n);
var y = new Array(n);
var vx = new Array(n);
var vy = new Array(n);

//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

function setup() {
	createCanvas(windowWidth, windowHeight);
	fill(0, 32);
	reset();
}

//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

function draw() {
	noStroke();
	rect(0, 0, width, height);

	for (let i = 0; i < n; i++) {
		let dx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - x[i];
		let dy = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - y[i];

		let d = sqrt(dx*dx + dy*dy);
		if (d < 1) d = 1;

		let f = sin(d * 0.04) * m[i] / d;

		vx[i] = vx[i] * 0.5 + f * dx;
		vy[i] = vy[i] * 0.5 + f * dy;
	}

	for (let i = 0; i < n; i++) {
		x[i] += vx[i];
		y[i] += vy[i];

		if (x[i] < 0) x[i] = width;
		else if (x[i] > width) x[i] = 0;

		if (y[i] < 0) y[i] = height;
		else if (y[i] > height) y[i] = 0;

		if (m[i] < 0) stroke(128, 128, 255);
		else stroke(0, 255, 255);

		point(x[i], y[i]);
	}
}

//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

function reset() {
	for (let i = 0; i < n; i++) {
		m[i] = randomGaussian() * 16;
		x[i] = random(width);
		y[i] = random(height);
	}
}

//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

function mousePressed() {
	reset();
}
